pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!(r#"{{"v":2,"hello":"{}"}}"#, escape_json_string(name)),
    }
}

fn escape_json_string(value: &str) -> String {
    let mut escaped = String::new();
    for ch in value.chars() {
        match ch {
            '"' => escaped.push_str(r#"\""#),
            '\\' => escaped.push_str(r#"\\"#),
            '\n' => escaped.push_str(r#"\n"#),
            '\r' => escaped.push_str(r#"\r"#),
            '\t' => escaped.push_str(r#"\t"#),
            ch if ch.is_control() => escaped.push_str(&format!(r#"\u{:04x}"#, ch as u32)),
            ch => escaped.push(ch),
        }
    }
    escaped
}

fn decode_v2_hello(bytes: &str) -> Option<String> {
    let prefix = r#"{"v":2,"hello":"#;
    let encoded = bytes.strip_prefix(prefix)?.strip_suffix('"')?;
    let mut decoded = String::new();
    let mut chars = encoded.chars();

    while let Some(ch) = chars.next() {
        if ch != '\\' {
            decoded.push(ch);
            continue;
        }

        match chars.next()? {
            '"' => decoded.push('"'),
            '\\' => decoded.push('\\'),
            '/' => decoded.push('/'),
            'b' => decoded.push('\u{0008}'),
            'f' => decoded.push('\u{000c}'),
            'n' => decoded.push('\n'),
            'r' => decoded.push('\r'),
            't' => decoded.push('\t'),
            'u' => {
                let code = chars.by_ref().take(4).collect::<String>();
                if code.len() != 4 || !code.chars().all(|digit| digit.is_ascii_hexdigit()) {
                    return None;
                }
                decoded.push(char::from_u32(u32::from_str_radix(&code, 16).ok()?)?);
            }
            _ => return None,
        }
    }

    Some(decoded)
}

