    31 | fn escape_json_string(value: &str) -> String {
    32 |     let mut escaped = String::new();
    33 |     for ch in value.chars() {
    34 |         match ch {
    35 |             '"' => escaped.push_str(r#"\""#),
    36 |             '\\' => escaped.push_str(r#"\\"#),
    37 |             '\n' => escaped.push_str(r#"\n"#),
    38 |             '\r' => escaped.push_str(r#"\r"#),
    39 |             '\t' => escaped.push_str(r#"\t"#),
    40 |             ch if ch.is_control() => escaped.push_str(&format!(r#"\u{:04x}"#, ch as u32)),
    41 |             ch => escaped.push(ch),
    42 |         }
    43 |     }
    44 |     escaped
    45 | }
