    53 | fn decode_v2_hello(bytes: &str) -> Option<String> {
    54 |     let prefix = r#"{"v":2,"hello":"#;
    55 |     let encoded = bytes.strip_prefix(prefix)?.strip_suffix('"')?;
    56 |     let mut decoded = String::new();
    57 |     let mut chars = encoded.chars();
    58 | 
    59 |     while let Some(ch) = chars.next() {
    60 |         if ch != '\\' {
    61 |             decoded.push(ch);
    62 |             continue;
    63 |         }
    64 | 
    65 |         match chars.next()? {
    66 |             '"' => decoded.push('"'),
    67 |             '\\' => decoded.push('\\'),
    68 |             '/' => decoded.push('/'),
    69 |             'b' => decoded.push('\u{0008}'),
    70 |             'f' => decoded.push('\u{000c}'),
    71 |             'n' => decoded.push('\n'),
    72 |             'r' => decoded.push('\r'),
    73 |             't' => decoded.push('\t'),
    74 |             'u' => {
    75 |                 let code = chars.by_ref().take(4).collect::<String>();
    76 |                 if code.len() != 4 || !code.chars().all(|digit| digit.is_ascii_hexdigit()) {
    77 |                     return None;
    78 |                 }
    79 |                 decoded.push(char::from_u32(u32::from_str_radix(&code, 16).ok()?)?);
    80 |             }
    81 |             _ => return None,
    82 |         }
    83 |     }
    84 | 
    85 |     Some(decoded)
    86 | }
